package in.tucor.api.buyer; import org.springframework.data.jpa.repository.*; import java.util.*; public interface BuyerPaymentRepository extends JpaRepository<BuyerPayment,UUID>{List<BuyerPayment> findByBuyerIdOrderByCreatedAtDesc(UUID buyerId); boolean existsByBuyerIdAndOrderIdAndStatusIn(UUID buyerId,UUID orderId,Collection<String> statuses);@Query("select p from BuyerPayment p join BuyerOrder o on o.id=p.orderId join MarketListing l on l.id=o.listingId where l.sellerId=:sellerId order by p.createdAt desc") List<BuyerPayment> findForSeller(UUID sellerId);}
